CREATE FUNCTION public.pe_replace_once(_definition text,_old text,_new text) RETURNS text LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (length(_definition)-length(replace(_definition,_old,'')))/length(_old)<>1 THEN RAISE EXCEPTION 'Expense function assertion failed: %',_old; END IF; RETURN replace(_definition,_old,_new); END $$;
REVOKE ALL ON FUNCTION public.pe_replace_once(text,text,text) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE d text; BEGIN
 SELECT pg_get_functiondef('public.pe_action(text,jsonb)'::regprocedure) INTO d;
 d:=pe_replace_once(d,'FROM profiles p WHERE p.collaborator_id=lead AND p.user_id<>auth.uid()','FROM auth.users p JOIN collaborators lc ON lc.email=p.email WHERE lc.id=lead AND p.id<>auth.uid()');
 d:=pe_replace_once(d,'SELECT p.user_id,''expense_approval_requested''','SELECT p.id,''expense_approval_requested''');
 d:=pe_replace_once(d,'FROM bank_accounts WHERE id=e.paid_from_account_id AND entity_id=ent AND active','FROM bank_accounts WHERE id=e.paid_from_account_id AND entity_id=ent AND is_active AND archived_at IS NULL');
 d:=pe_replace_once(d,' IF (_data->>''originalAmount'')::numeric<=0',' IF coalesce(_data->>''paidBy'',''personal'')=''personal'' AND NOT EXISTS(SELECT 1 FROM collaborators WHERE id=nullif(_data->>''collaboratorId'','''')::uuid AND archived_at IS NULL) THEN RAISE EXCEPTION ''Choose an active collaborator''; END IF; IF coalesce(_data->>''paidBy'',''personal'')=''personal'' AND nullif(_data->>''collaboratorId'','''')::uuid IS DISTINCT FROM get_my_collaborator_id() AND NOT pe_finance_access(ent) THEN RAISE EXCEPTION ''Only Finance can record another payer''; END IF; IF (_data->>''originalAmount'')::numeric<=0');
 d:=pe_replace_once(d,' IF e.purchase_document_id IS NOT NULL THEN RAISE EXCEPTION ''Confirmed receipt changes require finance review''; END IF;',' IF e.purchase_document_id IS NOT NULL AND NOT pe_finance_access(ent) THEN RAISE EXCEPTION ''Confirmed receipt changes require finance review''; END IF;');
 d:=pe_replace_once(d,' IF NOT pe_project_lead(e.project_id) OR e.approval_state<>''pending''',' IF (e.submitted_by=auth.uid() OR e.reimburse_collaborator_id=get_my_collaborator_id()) AND NOT has_role(auth.uid(),''admin'') THEN RAISE EXCEPTION ''Another approver must decide your expense''; END IF; IF NOT pe_project_lead(e.project_id) OR e.approval_state<>''pending''');
 d:=pe_replace_once(d,' n:=(_data->>''costAmount'')::numeric; remaining:=',' IF coalesce((_data->>''vatAmount'')::numeric,0)<0 OR coalesce((_data->>''vatAmount'')::numeric,0)+coalesce((SELECT sum(vat_amount) FROM project_expense_invoice_allocations WHERE line_id=l.id AND reversed_at IS NULL),0)>coalesce(l.vat_amount,0) THEN RAISE EXCEPTION ''VAT exceeds invoice line''; END IF; n:=(_data->>''costAmount'')::numeric; remaining:=');
 d:=pe_replace_once(d,' PERFORM set_config(''app.pe_action'','''',true);',' IF _action=''decide'' AND has_role(auth.uid(),''admin'') AND (e.submitted_by=auth.uid() OR e.reimburse_collaborator_id=get_my_collaborator_id()) THEN PERFORM pe_event(e.id,''adminApprovalOverride'',NULL,jsonb_build_object(''selfApproval'',true),reason); END IF; PERFORM set_config(''app.pe_action'','''',true);');
 EXECUTE d;
 SELECT pg_get_functiondef('public.pe_directory(uuid)'::regprocedure) INTO d; d:=pe_replace_once(d,'FROM bank_accounts WHERE entity_id=ent AND active','FROM bank_accounts WHERE entity_id=ent AND is_active AND archived_at IS NULL'); EXECUTE d;
 SELECT pg_get_functiondef('public.fin_confirm_queue_item(uuid,jsonb)'::regprocedure) INTO d;
 d:=pe_replace_once(d,'payment_status, created_by)','payment_status, created_by, project_expense_id)');
 d:=pe_replace_once(d,'ELSE ''awaiting_payment'' END, uid)','ELSE ''awaiting_payment'' END, uid, CASE WHEN EXISTS(SELECT 1 FROM pm_expenses WHERE id=r.source_project_expense_id AND workflow_version=2) THEN r.source_project_expense_id END)'); EXECUTE d;
 SELECT pg_get_functiondef('public.pe_match_purchase(uuid,uuid,numeric)'::regprocedure) INTO d;
 d:=pe_replace_once(d,' IF _amount<=0 OR _amount>fin_tx_open_balance(tx.id)',' IF EXISTS(SELECT 1 FROM project_expense_invoice_allocations WHERE expense_id=e.id AND reversed_at IS NULL) THEN RAISE EXCEPTION ''Reverse allocations before changing expense''; END IF; IF _amount<=0 OR _amount>fin_tx_open_balance(tx.id)'); EXECUTE d;
 SELECT pg_get_functiondef('public.pe_confirm_intake(uuid,uuid,jsonb)'::regprocedure) INTO d;
 d:=pe_replace_once(d,' doc:=(r->>''document_id'')::uuid;',' doc:=(r->>''document_id'')::uuid; IF EXISTS(SELECT 1 FROM financial_document_payments WHERE document_id=doc) OR EXISTS(SELECT 1 FROM finance_holder_reimbursements WHERE document_id=doc AND project_expense_id IS DISTINCT FROM e.id) THEN RAISE EXCEPTION ''Existing payments require a separately approved adaptation''; END IF;'); EXECUTE d;
END $$;
DO $$ DECLARE d text; branch text; first_pos integer; BEGIN SELECT pg_get_functiondef('public.fin_reconcile_candidates(uuid,text)'::regprocedure) INTO d;
 branch:='UNION ALL SELECT ''reimbursement_batch''::text,b.id,b.reference::text,c.nome::text,b.created_at::date,sum(a.reserved_amount)::numeric,sum(a.reserved_amount-a.settled_amount)::numeric,NULL::text,''reimbursement''::text FROM project_reimbursement_batches b JOIN project_reimbursement_allocations a ON a.batch_id=b.id AND a.reversed_at IS NULL JOIN collaborators c ON c.id=b.collaborator_id WHERE t.amount<0 AND b.entity_id=t.entity_id AND (s IS NULL OR c.nome ILIKE ''%''||s||''%'' OR b.reference ILIKE ''%''||s||''%'') GROUP BY b.id,c.nome HAVING sum(a.reserved_amount-a.settled_amount)>0 UNION ALL';
 IF (length(d)-length(replace(d,branch,'')))/length(branch)<>3 THEN RAISE EXCEPTION 'Candidate branch count changed'; END IF;
 d:=replace(d,branch,'UNION ALL'); first_pos:=position('UNION ALL' in d); d:=overlay(d placing branch from first_pos for length('UNION ALL'));
 d:=pe_replace_once(d,'AND q.created_expense_id IS NULL AND q.duplicate_of_document_id IS NULL','AND q.created_expense_id IS NULL AND q.duplicate_of_document_id IS NULL AND NOT EXISTS(SELECT 1 FROM pm_expenses e WHERE e.id=q.source_project_expense_id AND e.workflow_version=2 AND e.payment_source_type=''personal'')'); EXECUTE d;
END $$;
CREATE POLICY pe_flow_read_boundary ON public.pm_expenses AS RESTRICTIVE FOR SELECT TO authenticated USING (workflow_version<>2 OR (is_psa_staff() AND (submitted_by=auth.uid() OR pe_project_lead(project_id) OR pe_finance_access(entity_id))));
CREATE FUNCTION public.pe_personal_purchase_payment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM financial_documents d JOIN pm_expenses e ON e.id=d.project_expense_id WHERE d.id=NEW.document_id AND e.workflow_version=2 AND e.payment_source_type='personal') THEN RAISE EXCEPTION 'Personal expenses are settled only through reimbursement batches'; END IF; RETURN NEW; END $$;
CREATE TRIGGER aaa_pe_personal_purchase_payment_guard BEFORE INSERT OR UPDATE ON public.financial_document_payments FOR EACH ROW EXECUTE FUNCTION public.pe_personal_purchase_payment_guard();
CREATE FUNCTION public.pe_invoice_document_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.status='cancelled' OR (NEW.counterparty_client_id,NEW.entity_id,NEW.direction,NEW.doc_type) IS DISTINCT FROM (OLD.counterparty_client_id,OLD.entity_id,OLD.direction,OLD.doc_type)) AND EXISTS(SELECT 1 FROM project_expense_invoice_allocations a JOIN financial_document_lines l ON l.id=a.line_id WHERE l.document_id=OLD.id AND a.reversed_at IS NULL) THEN RAISE EXCEPTION 'Reverse expense allocations before changing invoice'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_invoice_document_guard BEFORE UPDATE ON public.financial_documents FOR EACH ROW EXECUTE FUNCTION public.pe_invoice_document_guard();
CREATE FUNCTION public.pe_invoice_tax_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.vat_amount,NEW.amount_inc_vat) IS DISTINCT FROM (OLD.vat_amount,OLD.amount_inc_vat) AND EXISTS(SELECT 1 FROM project_expense_invoice_allocations WHERE line_id=OLD.id AND reversed_at IS NULL) THEN RAISE EXCEPTION 'Reverse expense allocations before editing invoice line'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_invoice_tax_guard BEFORE UPDATE ON public.financial_document_lines FOR EACH ROW EXECUTE FUNCTION public.pe_invoice_tax_guard();